import{_ as t,o as d,c as a,a2 as s}from"./chunks/framework.Dx-TCpNt.js";const k=JSON.parse('{"title":"Build & Packaging","description":"KomaYomi ships in four shapes from one codebase: a browser app with a local server, a standalone server, an Electron desktop app, and a static online…","frontmatter":{"description":"KomaYomi ships in four shapes from one codebase: a browser app with a local server, a standalone server, an Electron desktop app, and a static online…"},"headers":[],"relativePath":"development/build.md","filePath":"development/build.md","lastUpdated":1794778569000}'),i={name:"development/build.md"};function o(n,e,r,c,l,p){return d(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="build-packaging" tabindex="-1">Build &amp; Packaging <a class="header-anchor" href="#build-packaging" aria-label="Permalink to &quot;Build &amp; Packaging&quot;">​</a></h1><p>KomaYomi ships in four shapes from one codebase: a browser app with a local server, a standalone server, an Electron desktop app, and a static online edition from a separate repository. This page lists the commands and the differences that actually matter when you change code.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Node.js 22 or newer with npm.</li><li>The batch CLI relies on Node&#39;s TypeScript support. Node 22.6–23.5 needs <code>--experimental-strip-types</code>; Node 23.6+ enables it by default, and Node 26 runs the <code>.ts</code> entry directly.</li><li>Desktop packaging targets Windows x64 by default (<code>electron-builder.yml</code>); the server itself runs anywhere Node runs.</li></ul><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th><th>Output</th></tr></thead><tbody><tr><td><code>npm run dev</code></td><td>Vite dev server plus the API middleware on <code>127.0.0.1:5173</code> (next free port if busy).</td><td>none</td></tr><tr><td><code>npm run build</code></td><td>Type-check the project and build the frontend.</td><td><code>dist/</code></td></tr><tr><td><code>npm run preview</code></td><td>Serve the built frontend with the same API middleware.</td><td>—</td></tr><tr><td><code>npm run server:build</code></td><td>Bundle <code>server/app.ts</code> and <code>server/standalone.ts</code> with esbuild.</td><td><code>dist-server/app.mjs</code>, <code>dist-server/standalone.mjs</code></td></tr><tr><td><code>npm start</code></td><td>Run the bundled standalone server.</td><td>HTTP on <code>127.0.0.1:3921</code></td></tr><tr><td><code>npm run desktop</code></td><td>Build, bundle the server and open Electron.</td><td>window</td></tr><tr><td><code>npm run dist:win</code></td><td>NSIS installer and portable executable.</td><td><code>release/</code></td></tr><tr><td><code>npm run dist:dir</code></td><td>Unpacked app for a quick desktop sanity check.</td><td><code>release/win-unpacked/</code></td></tr><tr><td><code>npm run docker:up</code></td><td>Build and run the container with bind mounts.</td><td><code>http://127.0.0.1:3921</code></td></tr><tr><td><code>npm run docs:dev</code></td><td>VitePress dev server at the server root (<code>DOCS_BASE=/</code>).</td><td><code>127.0.0.1:5174</code></td></tr><tr><td><code>npm run docs:build</code></td><td>Build this site (dead links fail the build).</td><td><code>docs/.vitepress/dist/</code></td></tr></tbody></table><h2 id="local-development" tabindex="-1">Local development <a class="header-anchor" href="#local-development" aria-label="Permalink to &quot;Local development&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>There is no second process: <code>server/plugin.ts</code> mounts <code>createMangaHandler</code> as Vite middleware for both <code>configureServer</code> and <code>configurePreviewServer</code>. A request to <code>/api/library</code> is handled in the same event loop as the page, which is why a server-side <code>console.log</code> shows up in the terminal that runs Vite.</p><p>Vite serves the frontend from <code>src/</code>; the server reads <code>raw/</code> and <code>data/</code> relative to the repository root.</p><h2 id="production-build" tabindex="-1">Production build <a class="header-anchor" href="#production-build" aria-label="Permalink to &quot;Production build&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p><code>npm run build</code> runs <code>tsc -b</code> first, so a type error fails the build. <code>server:build</code> bundles with <code>platform: node</code>, <code>format: esm</code>, <code>target: node20</code>, and injects a <code>createRequire</code> banner because <code>pngjs</code> and <code>jpeg-js</code> still call <code>require</code>.</p><p><code>npm start</code> expects <code>dist/</code> to exist; <code>server/standalone.ts</code> exits with <code>CLI_MISSING_STATIC_DIR</code> if it does not. Configuration is environment-only:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>HOST</code></td><td><code>127.0.0.1</code></td><td>Listen address. Set <code>0.0.0.0</code> only to allow LAN access; the API has no login.</td></tr><tr><td><code>PORT</code></td><td><code>3921</code></td><td>Listen port.</td></tr><tr><td><code>RAW_DIR</code></td><td><code>&lt;cwd&gt;/raw</code></td><td>Manga images.</td></tr><tr><td><code>DATA_DIR</code></td><td><code>&lt;cwd&gt;/data</code></td><td>JSON data.</td></tr><tr><td><code>EXPORT_DIR</code></td><td><code>&lt;cwd&gt;/exports</code></td><td>Generated files.</td></tr><tr><td><code>STATIC_DIR</code></td><td><code>&lt;cwd&gt;/dist</code></td><td>Built frontend.</td></tr><tr><td><code>MANGA_LOCALE</code></td><td>auto</td><td>UI locale hint: <code>en</code>, <code>zh</code> or <code>ja</code>.</td></tr><tr><td><code>LOG_LEVEL</code></td><td><code>info</code></td><td><code>debug</code>, <code>info</code>, <code>warn</code>, <code>error</code>.</td></tr></tbody></table><h2 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist:win</span></span></code></pre></div><p><code>electron/main.cjs</code> loads <code>dist-server/app.mjs</code> in-process, serves <code>dist/</code> and opens a window. Data is not bundled: on first launch the app asks for a library folder and remembers it in <code>%APPDATA%/manga-memo/config.json</code>, so <code>raw/</code>, <code>data/</code> and <code>exports/</code> stay where you keep your library.</p><p>Packaging configuration lives in <code>electron-builder.yml</code>. Only <code>dist/</code>, <code>dist-server/</code>, <code>electron/</code> and <code>package.json</code> are packed; the bundled server already contains its dependencies, so no <code>node_modules</code> is shipped.</p><h2 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre></div><p>The container runs <code>dist-server/standalone.mjs</code> and binds <code>raw/</code>, <code>data/</code> and <code>exports/</code> from the host. It is intended for a local machine: there are no accounts and no authentication, so do not expose the port publicly.</p><h2 id="the-static-online-edition" tabindex="-1">The static online edition <a class="header-anchor" href="#the-static-online-edition" aria-label="Permalink to &quot;The static online edition&quot;">​</a></h2><p>The static edition is a separate project, <code>https://github.com/PayayaKamo/KomaYomi-online</code>, built from a browser-only subset. It shares the page format and the project-file reader, but it cannot scan folders, run panel detection, load plugins or talk to WebDAV because none of those can run in a browser tab. Work saved there lives in IndexedDB.</p><p>When you add a feature, decide early which shape it belongs to:</p><table tabindex="0"><thead><tr><th>Change</th><th>Local server</th><th>Static edition</th></tr></thead><tbody><tr><td>A new field in a page document</td><td>Add it to <code>shared/</code> and the server normalizer.</td><td>Works if it lives in <code>shared/</code>.</td></tr><tr><td>A new detector or plugin hook</td><td><code>server/detect.ts</code>, <code>server/plugins.ts</code>.</td><td>Not available.</td></tr><tr><td>A new dialog or view</td><td><code>src/components/</code>.</td><td>Usually portable if it only calls existing API methods.</td></tr><tr><td>Filesystem, process or network access</td><td>Server only.</td><td>Not available.</td></tr></tbody></table><h2 id="regenerating-detection-baselines" tabindex="-1">Regenerating detection baselines <a class="header-anchor" href="#regenerating-detection-baselines" aria-label="Permalink to &quot;Regenerating detection baselines&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/manga-cli.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> regress</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/manga-cli.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> regress</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update</span></span></code></pre></div><p>The first command compares current panel counts with <code>scripts/detect-baseline.json</code>; <code>--update</code> rewrites the baseline. Review the diff before committing it — a baseline update is a promise that the new counts are correct.</p><h2 id="before-opening-a-pull-request" tabindex="-1">Before opening a pull request <a class="header-anchor" href="#before-opening-a-pull-request" aria-label="Permalink to &quot;Before opening a pull request&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i18n:scan</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p><code>i18n:scan</code> is non-strict by default; CI treats new hard-coded Chinese strings in <code>src/</code> as a failure. <code>docs:build</code> fails on a dead link, which is the cheapest way to catch a renamed page across three locales.</p>`,32)])])}const u=t(i,[["render",o]]);export{k as __pageData,u as default};
